-- taskCloudService: Legacy column additions for databases created before dataMigrate
-- Each ALTER TABLE is wrapped in an idempotent check so this file is safe to run
-- on both new databases (where 001_schema.sql already has all columns) and old ones.
-- Applied once via data_migrate_log tracking.

-- Helper: add column if not already present
-- cloud_oauth_tokens legacy columns
SET @stmt = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'cloud_oauth_tokens' AND COLUMN_NAME = 'company_id') = 0, 'ALTER TABLE cloud_oauth_tokens ADD COLUMN company_id VARCHAR(64) DEFAULT \'\'', 'SELECT 1'); PREPARE s FROM @stmt; EXECUTE s; DEALLOCATE PREPARE s;
SET @stmt = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'cloud_oauth_tokens' AND COLUMN_NAME = 'platform_type') = 0, 'ALTER TABLE cloud_oauth_tokens ADD COLUMN platform_type VARCHAR(64) DEFAULT \'aliyun\'', 'SELECT 1'); PREPARE s FROM @stmt; EXECUTE s; DEALLOCATE PREPARE s;
SET @stmt = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'cloud_oauth_tokens' AND COLUMN_NAME = 'authorization_type') = 0, 'ALTER TABLE cloud_oauth_tokens ADD COLUMN authorization_type VARCHAR(64) DEFAULT \'oauth\'', 'SELECT 1'); PREPARE s FROM @stmt; EXECUTE s; DEALLOCATE PREPARE s;
SET @stmt = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'cloud_oauth_tokens' AND COLUMN_NAME = 'scope') = 0, 'ALTER TABLE cloud_oauth_tokens ADD COLUMN scope TEXT', 'SELECT 1'); PREPARE s FROM @stmt; EXECUTE s; DEALLOCATE PREPARE s;

