-- cloud_tenant_installed_images data migration: migrate legacy company_id → tenant_id
-- Safe on fresh schemas (skips when company_id column does not exist)
SET @stmt = IF(
  (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'cloud_tenant_installed_images' AND COLUMN_NAME = 'company_id') > 0,
  'UPDATE cloud_tenant_installed_images SET tenant_id = company_id WHERE tenant_id = \'\' AND company_id != \'\'',
  'SELECT 1'
); PREPARE s FROM @stmt; EXECUTE s; DEALLOCATE PREPARE s;

SET @stmt = IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'cloud_tenant_installed_images' AND INDEX_NAME = 'idx_tii_tenant') = 0, 'CREATE INDEX idx_tii_tenant ON cloud_tenant_installed_images(tenant_id)', 'SELECT 1'); PREPARE s FROM @stmt; EXECUTE s; DEALLOCATE PREPARE s;
